<script setup lang="ts">
import QRCode from 'qrcode'
definePageMeta({layout:'custom'})
const {t}=useI18n(),route=useRoute(),{bizErrorMessage}=useBizError()
const record=ref<any>(null),error=ref(''),loading=ref(true),qr=ref(''),copies=ref(1),offset=ref(0)
const valid=computed(()=>Number.isInteger(copies.value)&&copies.value>=1&&copies.value<=100&&Number.isInteger(offset.value)&&offset.value>=0&&offset.value<=9)
const pages=computed(()=>{if(!valid.value)return [];const labels=Array.from({length:offset.value+copies.value},(_,index)=>index>=offset.value);return Array.from({length:Math.ceil(labels.length/10)},(_,index)=>labels.slice(index*10,index*10+10))})
const barcodeValid=computed(()=>record.value?.code&&/^[\x20-\x7E]+$/.test(record.value.code))
const fontSize=computed(()=>Math.min(50,210/Math.max(1,String(record.value?.code||'').length)*1.5)+'px')
const print=async()=>{await document.fonts.ready;await nextTick();window.print()}
onMounted(async()=>{record.value=await httpRequest<any>('/api/warehouse/location/'+Number(route.params.id),{onError:e=>error.value=bizErrorMessage(e)});if(record.value){try{qr.value=await QRCode.toDataURL(record.value.code,{errorCorrectionLevel:'M',margin:4,width:416})}catch{error.value=t('location-label.code-error')}}loading.value=false})
useHead({title:()=>t('location-label.title')+' · '+(record.value?.code||'')})
</script>
<template><div class="w-location-label-print w-scope"><div class="toolbar"><NuxtLink class="w-label-back" :to="'/location/detail/'+route.params.id">{{record?.code||t('nav.location')}}</NuxtLink><span class="paper-type">A4 · 10 × 99.1 × 57 mm</span><WField :label="t('location-label.copies')"><WInput v-model.number="copies" type="number" min="1" max="100"/></WField><WField :label="t('location-label.offset')"><WSelect v-model="offset" :options="Array.from({length:10},(_,value)=>({value,label:String(value+1)}))"/></WField><WButton icon="printer" :disabled="loading||!record||!qr||!valid||!!error" @click="print">{{t('button.print-to-pdf')}}</WButton></div><WAlert v-if="error" tone="block" :title="error"/><WAlert v-if="!valid" tone="block" :title="t('location-label.invalid')"/><WEmptyState v-if="loading" :title="t('common.status.loading')"/><p class="hint">{{t('location-label.hint')}}</p><div v-if="record&&qr" class="paper-scroll"><section v-for="(page,index) in pages" :key="index" class="label-sheet" :aria-label="`${record.code} · ${index+1}/${pages.length}`"><div v-for="(filled,slot) in page" :key="slot" class="label" :class="{blank:!filled}"><template v-if="filled"><header><span>{{record.warehouse?.name||record.warehouse_name}}</span><b v-if="record.location_type!=='standard'">{{record.location_type==='damaged'?'DAMAGED':'RETURN'}}</b></header><strong class="code" :style="{fontSize}">{{record.code}}</strong><img class="qr" :src="qr" :alt="'QR '+record.code"/><Barcode v-if="barcodeValid" class="code128" :id="`label-${index}-${slot}`" :value="record.code" :options="{displayValue:false,width:1.2,height:40,margin:10}"/><small v-else class="unicode-code">{{record.code}}</small></template></div></section></div></div></template>
<style scoped>
.w-location-label-print{min-height:100vh;padding:24px;background:#F6F7FA;color:#151923}.toolbar{display:flex;align-items:end;flex-wrap:wrap;gap:16px;max-width:1000px;margin:0 auto 16px}.w-label-back{color:#5F1FE6;text-decoration:none;font-size:14px;font-weight:500;align-self:center}.paper-type{font-size:12px;line-height:18px;color:#656C7A;align-self:center;margin-right:auto}.toolbar>.w-field{width:110px}.hint{font-size:12px;line-height:18px;color:#656C7A;max-width:794px;margin:0 auto 16px}.paper-scroll{overflow:auto}.label-sheet{box-sizing:border-box;width:210mm;height:297mm;background:white;padding:6mm 4.65mm;display:grid;grid-template-columns:repeat(2,99.1mm);grid-template-rows:repeat(5,57mm);column-gap:2.5mm;margin:0 auto 24px;font-family:Inter,'Noto Sans SC','Noto Sans JP',sans-serif;line-height:1.25}.label{box-sizing:border-box;border:1px dashed #CDD1DA;border-radius:10px;padding:13px 15px 12px;display:grid;grid-template-columns:minmax(0,1fr) 104px;grid-template-rows:auto minmax(0,1fr) auto;column-gap:12px;overflow:hidden}.label.blank{border-color:transparent}.label header{grid-column:1/-1;display:flex;justify-content:space-between;gap:8px;align-items:center;padding-bottom:6px;border-bottom:1px solid #151923;font-size:9px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;overflow-wrap:anywhere}.label header b{border:1.5px solid #151923;padding:1px 6px;letter-spacing:.08em}.code{align-self:center;font-weight:900;letter-spacing:.01em;line-height:1;overflow-wrap:anywhere;font-variant-numeric:tabular-nums;min-width:0}.qr{grid-row:2/4;grid-column:2;align-self:center;display:block;width:104px;height:104px;image-rendering:pixelated}.code128{grid-row:3;grid-column:1;max-width:100%;height:48px}.unicode-code{font-size:10px;overflow-wrap:anywhere}@media(max-width:820px){.w-location-label-print{padding:16px}.label-sheet{margin-left:0}.toolbar{gap:12px}}@media print{.w-location-label-print{padding:0;background:white}.toolbar,.hint,.w-alert{display:none}.paper-scroll{overflow:visible}.label-sheet{margin:0;break-after:page}.label-sheet:last-child{break-after:auto}.label{break-inside:avoid;border-color:transparent}}
</style>
<style>@page{size:A4;margin:0;@bottom-right{content:none}}@media print{html,body{margin:0!important;padding:0!important;background:white!important}.nuxt-devtools-panel,.nuxt-devtools-toggle{display:none!important}}</style>
